const item = $input.first().json;
const msg = item.message || item.edited_message || {};
const text = typeof msg.text === 'string' ? msg.text.trim() : '';
const chatId = msg.chat && msg.chat.id !== undefined ? msg.chat.id : null;
const re1 = /^\/?(?:done|complete|completed|finish|finished)(?:@\w+)?\s*(?:task\s*)?#?\s*(\d+)\s*[.!]?$/i;
const re2 = /^(?:task\s*)?#?(\d+)\s+(?:is\s+)?(?:done|complete|completed|finished)\s*[.!]?$/i;
const m = text.match(re1) || text.match(re2);
if (m) {
  return [{ json: { valid: true, taskNumber: parseInt(m[1], 10), chatId, text } }];
}
return [{ json: { valid: false, chatId, text, replyText: `I didn't understand that. To complete a task, send something like <code>done 2</code> (also works: complete 2, completed 2, finish 2).` } }];

const TZ = 'Africa/Cairo';
const now = $now.setZone(TZ);

let cmd = null;
try {
  if ($('Parse Command').isExecuted) cmd = $('Parse Command').first().json;
} catch (e) { cmd = null; }

const base = {
  mode: cmd ? 'telegram' : 'report',
  chatId: cmd ? cmd.chatId : null,
  requestedNumber: cmd ? cmd.taskNumber : null,
  dateLabel: now.toFormat('d LLLL yyyy'),
  todayISO: now.toISODate(),
};

const toDT = (o) => {
  if (!o) return null;
  let dt = null;
  if (o.dateTime) dt = DateTime.fromISO(o.dateTime, { setZone: true }).setZone(TZ);
  else if (o.date) dt = DateTime.fromISO(String(o.date).slice(0, 10), { zone: TZ });
  return dt && dt.isValid ? dt : null;
};

const clean = (html) => String(html || '')
  .replace(/<br\s*\/?>/gi, '\n')
  .replace(/<\/(p|div|li|ul|ol)>/gi, '\n')
  .replace(/<[^>]+>/g, '')
  .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
  .split('\n')
  .filter((l) => !/^\s*status:\s*(completed|pending)\s*$/i.test(l))
  .join('\n').replace(/\n{3,}/g, '\n\n').trim();

const tasks = [];
for (const item of $input.all()) {
  const e = item.json;
  if (!e || !e.id || e.status === 'cancelled') continue;
  const start = toDT(e.start);
  if (!start) continue;
  const end = toDT(e.end);
  const allDay = !!(e.start && e.start.date && !e.start.dateTime);
  const rawDescription = typeof e.description === 'string' ? e.description : '';
  const originalSummary = typeof e.summary === 'string' ? e.summary : '';
  const completed = /(^|\n|>)[ \t]*status:\s*completed/i.test(rawDescription) || /^\s*\[done\]/i.test(originalSummary);
  const startFmt = start.toISODate() === base.todayISO ? 'HH:mm' : 'd LLL HH:mm';
  let timeLabel;
  if (allDay) {
    timeLabel = 'All day';
  } else if (end) {
    const endFmt = end.toISODate() === start.toISODate() ? 'HH:mm' : 'd LLL HH:mm';
    timeLabel = start.toFormat(startFmt) + ' \u2013 ' + end.toFormat(endFmt);
  } else {
    timeLabel = start.toFormat(startFmt);
  }
  const createdMs = Date.parse(e.created) || 0;
  tasks.push({
    eventId: e.id,
    title: originalSummary.trim() || '(No title)',
    originalSummary,
    startISO: start.toISO(),
    endISO: end ? end.toISO() : null,
    startMs: start.toMillis(),
    endMs: end ? end.toMillis() : Number.MAX_SAFE_INTEGER,
    createdMs,
    allDay,
    timeLabel,
    rawDescription,
    description: clean(rawDescription),
    completed,
    status: completed ? 'Completed' : 'Pending',
    url: e.htmlLink || '',
  });
}

// Deterministic order (shared by the email and Telegram completion):
// start, end, all-day first, creation time (oldest first), then event ID.
// Title and status are intentionally NOT used so numbering never shifts when a task is completed.
tasks.sort((a, b) => {
  if (a.startMs !== b.startMs) return a.startMs - b.startMs;
  if (a.endMs !== b.endMs) return a.endMs < b.endMs ? -1 : 1;
  if (a.allDay !== b.allDay) return a.allDay ? -1 : 1;
  if (a.createdMs !== b.createdMs) return a.createdMs - b.createdMs;
  return a.eventId < b.eventId ? -1 : (a.eventId > b.eventId ? 1 : 0);
});

if (!tasks.length) return [{ json: { ...base, noTasks: true } }];
return tasks.map((t, i) => ({ json: { ...base, noTasks: false, taskNumber: i + 1, ...t } }));

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const items = $input.all().map((i) => i.json);
const dateLabel = (items[0] && items[0].dateLabel) || '';
const tasks = items.filter((t) => !t.noTasks);

const header = `<tr><td style='background:#1f2937;padding:24px 28px;'><div style='font-size:12px;letter-spacing:2px;color:#9ca3af;'>${esc(dateLabel)}</div><div style='font-size:24px;font-weight:700;color:#ffffff;margin-top:4px;'>TODAY'S TASKS</div></td></tr>`;
const wrap = (inner) => `<div style='background:#f3f4f6;padding:24px 12px;font-family:Arial,Helvetica,sans-serif;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='max-width:640px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb;'>${inner}</table></div>`;

if (!tasks.length) {
  const body = `<tr><td style='padding:28px;font-size:16px;color:#374151;line-height:1.5;'>You have no tasks scheduled for today.<br><br><span style='font-size:13px;color:#6b7280;'>Nothing was found in your Google Calendar for ${esc(dateLabel)}.</span></td></tr>`;
  return [{ json: { subject: `No tasks scheduled today \u2014 ${dateLabel}`, html: wrap(header + body) } }];
}

const cards = tasks.map((t) => {
  const badge = t.completed
    ? `<span style='display:inline-block;padding:2px 10px;border-radius:999px;background:#dcfce7;color:#166534;font-size:12px;font-weight:600;'>Completed</span>`
    : `<span style='display:inline-block;padding:2px 10px;border-radius:999px;background:#fef3c7;color:#92400e;font-size:12px;font-weight:600;'>Pending</span>`;
  const desc = t.description ? esc(t.description).replace(/\n/g, '<br>') : `<span style='color:#9ca3af;'>No description</span>`;
  const link = t.url ? `<div style='margin-top:10px;font-size:14px;'><a href='${esc(t.url)}' style='color:#2563eb;text-decoration:none;font-weight:600;'>Open in Google Calendar</a></div>` : '';
  return `<tr><td style='padding:18px 28px;border-bottom:1px solid #e5e7eb;'><div dir='auto' style='font-size:17px;font-weight:700;color:#111827;'>#${t.taskNumber} \u2014 ${esc(t.title)}</div><div style='font-size:14px;color:#4b5563;margin-top:4px;'>${esc(t.timeLabel)}</div><div style='margin-top:8px;'>Status: ${badge}</div><div dir='auto' style='font-size:14px;color:#374151;margin-top:8px;line-height:1.5;'><b>Description:</b> ${desc}</div>${link}</td></tr>`;
}).join('');

const doneCount = tasks.filter((t) => t.completed).length;
const summary = `<tr><td style='padding:14px 28px;background:#f9fafb;border-bottom:1px solid #e5e7eb;font-size:13px;color:#6b7280;'>${tasks.length} task${tasks.length === 1 ? '' : 's'} \u00b7 ${doneCount} completed \u00b7 ${tasks.length - doneCount} pending</td></tr>`;
const footer = `<tr><td style='padding:16px 28px;font-size:12px;color:#9ca3af;'>Reply on Telegram with <b>done N</b> (for example <b>done 2</b>) to mark a task as completed.</td></tr>`;

return [{ json: { subject: `Today's Tasks \u2014 ${dateLabel} (${tasks.length})`, html: wrap(header + summary + cards + footer) } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const items = $input.all().map((i) => i.json);
const first = items[0] || {};
const chatId = first.chatId;
const n = Number(first.requestedNumber);
const reply = (outcome, replyText, extra = {}) => [{ json: { outcome, chatId, replyText, ...extra } }];

if (first.noTasks) return reply('no_tasks', 'There are no tasks scheduled for today.');

const task = items.find((t) => t.taskNumber === n);
if (!task) {
  return reply('invalid_number', `\u274c I couldn't find task #${n} in today's tasks. Today has ${items.length} task${items.length === 1 ? '' : 's'} (#1\u2013#${items.length}).`);
}
if (task.completed) {
  return reply('already_done', `\u2139\ufe0f Task #${n} is already marked as completed: ${esc(task.title)}`);
}

const raw = task.rawDescription || '';
const statusRe = /(^|\n|>)([ \t]*)status:[^\n<]*/i;
const hasHtml = /<\s*(br|p|div|ul|ol|li|b|i|a|span)\b/i.test(raw);
let newDescription;
if (statusRe.test(raw)) newDescription = raw.replace(statusRe, '$1$2Status: Completed');
else if (raw.trim()) newDescription = raw.replace(/\s+$/, '') + (hasHtml ? '<br><br>' : '\n\n') + 'Status: Completed';
else newDescription = 'Status: Completed';

const orig = (task.originalSummary || '').trim();
const newSummary = /^\[done\]/i.test(orig) ? orig : (orig ? '[DONE] ' + orig : '[DONE]');

return reply('ready', '', { eventId: task.eventId, taskNumber: n, title: task.title, newDescription, newSummary });

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ctx = $('Resolve Task').first().json;
return [{ json: { chatId: ctx.chatId, replyText: `\u2705 Task #${ctx.taskNumber} marked as completed: ${esc(ctx.title)}` } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ctx = $('Resolve Task').first().json;
const err = $input.first().json.error;
let msg = typeof err === 'string' ? err : ((err && (err.message || err.description)) || JSON.stringify(err || {}));
msg = String(msg).slice(0, 300);
return [{ json: { chatId: ctx.chatId, replyText: `\u274c I couldn't update task #${ctx.taskNumber} (${esc(ctx.title)}) in Google Calendar: ${esc(msg)}` } }];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let cmd = null;
try {
  if ($('Parse Command').isExecuted) cmd = $('Parse Command').first().json;
} catch (e) { cmd = null; }
const err = $input.first().json.error;
let msg = typeof err === 'string' ? err : ((err && (err.message || err.description)) || JSON.stringify(err || {}));
msg = String(msg).slice(0, 300);
return [{ json: {
  mode: cmd ? 'telegram' : 'report',
  chatId: cmd ? cmd.chatId : null,
  replyText: `\u274c I couldn't read today's Google Calendar events: ${esc(msg)}`,
  subject: `\u26a0\ufe0f Daily tasks report failed \u2014 Google Calendar error`,
  html: `<div style='font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#111827;'><h2 style='margin:0 0 12px;'>Couldn't load today's tasks</h2><p>The workflow could not read your Google Calendar events.</p><p style='color:#b91c1c;'>${esc(msg)}</p><p style='color:#6b7280;font-size:13px;'>Check the Google Calendar credential in the "my tasks" workflow.</p></div>`,
} }];
